`timescale 1ns / 1ps
// AUTO-GENERATED by synthesis/tbgen.py. Do not edit by hand.
// Mode: asap; scheduled cycles: 3
// Rebuild this testbench when examples.txt or scheduling mode changes.
// Selectors (exactly from synthesis.codegen.view_list):
// fu_sel  0 = add0 (add0_observed)
// fu_sel  1 = sub0 (sub0_observed)
// fu_sel  2 = mul0 (mul0_observed)
// fu_sel  3 = X_1 (r_X_1)
// fu_sel  4 = Y_1 (r_Y_1)
// fu_sel  5 = Z_1 (r_Z_1)
// fu_sel  6 = Q_1 (r_Q_1)
// fu_sel  7 = A_0 (r_A_0)
// fu_sel  8 = B_0 (r_B_0)
// in_sel  0 = A_0
// in_sel  1 = B_0

module tb_synth_core;
    reg clk = 0;
    reg rst = 0;
    reg step = 0;
    reg [5:0] in_sel = 0;
    reg [7:0] in_val = 0;
    reg in_write = 0;
    reg [6:0] fu_sel = 0;
    wire [15:0] disp_val;
    wire [4:0] state;
    wire done;
    integer checks = 0;

    synth_core #(.W(16)) dut (
        .clk(clk), .rst(rst), .step(step),
        .in_sel(in_sel), .in_val(in_val), .in_write(in_write),
        .fu_sel(fu_sel), .disp_val(disp_val),
        .state(state), .done(done)
    );
    always #5 clk = ~clk;  // 100 MHz

    task reset_core;
    begin
        @(negedge clk); rst = 1; step = 0; in_write = 0;
        @(negedge clk); rst = 0; #1;
        if (state !== 5'd0 || done !== 1'b0)
            $fatal(1, "FAIL: reset did not return to LOAD");
    end
    endtask

    task load_input;
        input [5:0] sel;
        input [7:0] value;
    begin
        @(negedge clk); in_sel = sel; in_val = value; in_write = 1;
        @(negedge clk); in_write = 0; #1;
    end
    endtask

    task press_step;
    begin
        @(negedge clk); step = 1;
        @(negedge clk); step = 0; #1;
    end
    endtask

    task check_value;
        input [6:0] selector;
        input [15:0] expected;
        input [8*80-1:0] description;
    begin
        fu_sel = selector; #1;
        if (disp_val !== expected) begin
            $display("FAIL: %0s (fu_sel=%0d): got %0d (%h), expected %0d (%h), state=%0d",
                     description, selector, disp_val, disp_val, expected, expected, state);
            $fatal(1, "Incorrect synth_core output");
        end
        checks = checks + 1;
    end
    endtask

    task check_state;
        input [4:0] expected;
    begin
        if (state !== expected)
            $fatal(1, "Wrong state: got %0d, expected %0d", state, expected);
        if (done !== (expected == 5'd4))
            $fatal(1, "DONE flag mismatch in state %0d", state);
        checks = checks + 1;
    end
    endtask

    initial begin
        // Watchdog: catches stalled or nonterminating tests.
        // This delay is greater than all generated stimulus durations.
        // (Set according to number of test cases, inputs, cycles.)
        #(1920);
        $fatal(1, "TIMEOUT: generated testbench did not finish");
    end

    initial begin
        $display("AUTO TESTBENCH: 2 vectors, 3 arithmetic cycles");

        // ------------------- TEST VECTOR 1 -------------------
        $display("TEST 1 INPUTS: A_0=3, B_0=2");
        reset_core;
        // Reset must clear every saved input and result register.
        check_value(7'd7, 16'd0, "reset A_0");
        check_value(7'd8, 16'd0, "reset B_0");
        check_value(7'd3, 16'd0, "reset X_1");
        check_value(7'd4, 16'd0, "reset Y_1");
        check_value(7'd5, 16'd0, "reset Z_1");
        check_value(7'd6, 16'd0, "reset Q_1");
        load_input(6'd0, 8'd3);
        check_value(7'd7, 16'd3, "loaded A_0");
        load_input(6'd1, 8'd2);
        check_value(7'd8, 16'd2, "loaded B_0");
        check_state(5'd0);
        press_step;  // LOAD -> arithmetic cycle 1
        check_state(5'd1);
        // Arithmetic cycle 1: check active FU outputs, then write registers.
        check_value(7'd0, 16'd5, "cycle 1 add0: X_1");
        press_step;
        check_state(5'd2);
        check_value(7'd3, 16'd5, "cycle 1 stored X_1");
        // Arithmetic cycle 2: check active FU outputs, then write registers.
        check_value(7'd0, 16'd8, "cycle 2 add0: Y_1");
        check_value(7'd1, 16'd3, "cycle 2 sub0: Z_1");
        press_step;
        check_state(5'd3);
        check_value(7'd4, 16'd8, "cycle 2 stored Y_1");
        check_value(7'd5, 16'd3, "cycle 2 stored Z_1");
        // Arithmetic cycle 3: check active FU outputs, then write registers.
        check_value(7'd2, 16'd6, "cycle 3 mul0: Q_1");
        press_step;
        check_state(5'd4);
        check_value(7'd6, 16'd6, "cycle 3 stored Q_1");
        if (done !== 1'b1) $fatal(1, "DONE not asserted");
        // Verify every final visible register, including intermediate SSA results.
        check_value(7'd7, 16'd3, "final A_0");
        check_value(7'd8, 16'd2, "final B_0");
        check_value(7'd3, 16'd5, "final X_1");
        check_value(7'd4, 16'd8, "final Y_1");
        check_value(7'd5, 16'd3, "final Z_1");
        check_value(7'd6, 16'd6, "final Q_1");
        // Updated FU observation RTL remembers final result even at DONE.
        check_value(7'd0, 16'd8, "last add0");
        check_value(7'd1, 16'd3, "last sub0");
        check_value(7'd2, 16'd6, "last mul0");
        // Inputs cannot be overwritten after leaving LOAD mode.
        load_input(6'd0, 8'd255);
        check_value(7'd7, 16'd3, "write ignored after DONE");
        press_step;  // DONE should ignore extra steps
        check_state(5'd4);
        $display("TEST 1 PASSED");

        // ------------------- TEST VECTOR 2 -------------------
        $display("TEST 2 INPUTS: A_0=10, B_0=4");
        reset_core;
        // Reset must clear every saved input and result register.
        check_value(7'd7, 16'd0, "reset A_0");
        check_value(7'd8, 16'd0, "reset B_0");
        check_value(7'd3, 16'd0, "reset X_1");
        check_value(7'd4, 16'd0, "reset Y_1");
        check_value(7'd5, 16'd0, "reset Z_1");
        check_value(7'd6, 16'd0, "reset Q_1");
        load_input(6'd0, 8'd10);
        check_value(7'd7, 16'd10, "loaded A_0");
        load_input(6'd1, 8'd4);
        check_value(7'd8, 16'd4, "loaded B_0");
        check_state(5'd0);
        press_step;  // LOAD -> arithmetic cycle 1
        check_state(5'd1);
        // Arithmetic cycle 1: check active FU outputs, then write registers.
        check_value(7'd0, 16'd14, "cycle 1 add0: X_1");
        press_step;
        check_state(5'd2);
        check_value(7'd3, 16'd14, "cycle 1 stored X_1");
        // Arithmetic cycle 2: check active FU outputs, then write registers.
        check_value(7'd0, 16'd24, "cycle 2 add0: Y_1");
        check_value(7'd1, 16'd10, "cycle 2 sub0: Z_1");
        press_step;
        check_state(5'd3);
        check_value(7'd4, 16'd24, "cycle 2 stored Y_1");
        check_value(7'd5, 16'd10, "cycle 2 stored Z_1");
        // Arithmetic cycle 3: check active FU outputs, then write registers.
        check_value(7'd2, 16'd40, "cycle 3 mul0: Q_1");
        press_step;
        check_state(5'd4);
        check_value(7'd6, 16'd40, "cycle 3 stored Q_1");
        if (done !== 1'b1) $fatal(1, "DONE not asserted");
        // Verify every final visible register, including intermediate SSA results.
        check_value(7'd7, 16'd10, "final A_0");
        check_value(7'd8, 16'd4, "final B_0");
        check_value(7'd3, 16'd14, "final X_1");
        check_value(7'd4, 16'd24, "final Y_1");
        check_value(7'd5, 16'd10, "final Z_1");
        check_value(7'd6, 16'd40, "final Q_1");
        // Updated FU observation RTL remembers final result even at DONE.
        check_value(7'd0, 16'd24, "last add0");
        check_value(7'd1, 16'd10, "last sub0");
        check_value(7'd2, 16'd40, "last mul0");
        // Inputs cannot be overwritten after leaving LOAD mode.
        load_input(6'd0, 8'd255);
        check_value(7'd7, 16'd10, "write ignored after DONE");
        press_step;  // DONE should ignore extra steps
        check_state(5'd4);
        $display("TEST 2 PASSED");
        $display("ALL SYNTH_CORE TESTS PASSED (%0d checks)", checks);
        $finish;
    end
endmodule
